/**
 * The Components tab's preset tiles: every item the Craft editor's +Add toolbox offered (Rows and columns, Tabs,
 * Accordion, Tables, Navbars, Grids, Forms, Embeds, Maps ...), as the HTML-first snippet the converter makes for
 * a migrated site. `toolboxPresets.generated.ts` is generated by pagehub.dev `scripts/gen-toolbox-presets.mts`.
 */
import type { IconName } from "../../primitives/icons";
import { TOOLBOX_PRESETS, type ToolboxPreset } from "./toolboxPresets.generated";
import type { ToolTile } from "./ComponentsTab";

/**
 * Old toolbox items with no tile of their own, each because an element tile already inserts the same thing.
 * Keyed `<Craft component>/<preset label>`.
 */
export const TOOLBOX_EXCLUDED: Readonly<Record<string, string>> = {
  "Container/Section": "the Section element tile",
  "Text/Title": "the Heading element tile",
  "Text/Sub-title": "the Heading element tile",
  "Text/Paragraph": "the Text element tile",
  "Text/Rich content": "the Text element tile",
  "Icon/Icon": "the Icon element tile",
  "Image/Image": "the Image element tile (a bare image has no source to convert)",
  "Button/Button": "the Button element tile",
  "Link/Link": "the Link element tile",
  "FormElement/Input": "the Input element tile",
};

const ICON: Record<string, IconName> = {
  Layout: "box", Components: "box", Interactive: "click", Lists: "list", Tables: "layout-grid", Dividers: "minus", Navigation: "layout-navbar",
  Buttons: "click", Images: "photo", Grid: "layout-grid", Text: "text", Icons: "sparkles", Forms: "forms", Media: "photo", Embeds: "code",
};

export const presetKey = (p: ToolboxPreset) => `${p.component}/${p.label}`;

export const toolboxTiles = (): ToolTile[] =>
  TOOLBOX_PRESETS.filter((p) => !(presetKey(p) in TOOLBOX_EXCLUDED)).map((p) => ({
    key: `preset:${presetKey(p)}`,
    label: p.label,
    icon: ICON[p.category] ?? "box",
    category: p.category,
    description: p.description || undefined,
    insert: { snippet: p.snippet },
  }));
